 "content": "from collections import Counter, deque


def transform(grid):
    """Repair singleton color-noise pixels by restoring their local field color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    singleton = []

    # Find monochromatic 4-connected components. The true regions are extended
    # blocks; the overlaid marks are single-cell components.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) == 1:
                singleton.append(cells[0])

    # Restore each isolated mark from the surrounding pattern. Prefer the most
    # frequent 8-neighbor color, with orthogonal neighbors as a tie-breaker.
    for r, c in singleton:
        around = []
        orthogonal = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == dc == 0:
                    continue
                y, x = r + dr, c + dc
                if 0 <= y < h and 0 <= x < w:
                    around.append(grid[y][x])
                    if abs(dr) + abs(dc) == 1:
                        orthogonal.append(grid[y][x])
        counts = Counter(around)
        best = max(counts, key=lambda color: (counts[color], Counter(orthogonal)[color]))
        out[r][c] = best
    return out


